"""Source-bound two-vehicle Native plan for the first exact overtaking case."""

import hashlib
import json
from math import atan2, hypot, isfinite
from pathlib import Path

ASSIGNMENT = "heldout__C230259__NRS-484B-207-2__motor_vehicle_driver"
CASE = ASSIGNMENT + "__observed_gives_way_holds_speed"


def _point(value, name):
    if (not isinstance(value, list) or len(value) != 2 or
            not all(isinstance(x, (int, float)) and not isinstance(x, bool) and isfinite(x) for x in value)):
        raise ValueError("Invalid source " + name)
    return [float(x) for x in value]


def load_site(path, sha256):
    raw = Path(path).read_bytes()
    if hashlib.sha256(raw).hexdigest() != sha256:
        raise ValueError("Native overtaking site SHA-256 mismatch")
    site = json.loads(raw)
    if not isinstance(site, dict) or not site.get("map_name") or site.get("road_kind") != "road":
        raise ValueError("Original road site identity missing")
    start = _point(site.get("ego_start_xy_m"), "ego start")
    passing = _point(site.get("overtaker_start_xy_m"), "overtaker start")
    forward = _point(site.get("forward_xy"), "travel direction")
    length = hypot(*forward)
    if not .99 <= length <= 1.01:
        raise ValueError("Source travel direction must be unit length")
    forward = [x / length for x in forward]
    right = [forward[1], -forward[0]]
    delta = [passing[i] - start[i] for i in (0, 1)]
    longitudinal = sum(delta[i] * forward[i] for i in (0, 1))
    lateral = sum(delta[i] * right[i] for i in (0, 1))
    if not -20. <= longitudinal <= -6. or not -5. <= lateral <= -2.:
        raise ValueError("Overtaker must begin behind and to the left")
    for name in ("ego_road_id", "ego_lane_id", "overtaker_road_id", "overtaker_lane_id"):
        if type(site.get(name)) is not int:
            raise ValueError("Original waypoint identity missing: " + name)
    width = site.get("ego_right_clearance_m")
    if isinstance(width, bool) or not isinstance(width, (int, float)) or not isfinite(width) or width < 1.5:
        raise ValueError("No surveyed clearance for rightward engineering target")
    return site, start, passing, forward, right


def prepare(case_id, source, sha256):
    if case_id != CASE:
        raise ValueError("First exact overtaking case required")
    site, ego, passing, forward, right = load_site(source, sha256)
    project = lambda point, advance, shift: [point[i] + forward[i] * advance + right[i] * shift for i in (0, 1)]
    return {"case_id": case_id, "site_source": str(source), "site_sha256": sha256,
            "map_name": site["map_name"], "ego_start_xy_m": ego,
            "overtaker_start_xy_m": passing, "forward_xy": forward,
            "ego_target_xy_m": project(ego, 22., 0.6),
            "overtaker_target_xy_m": project(passing, 45., 0.),
            "ego_target_speed_mps": 4., "overtaker_target_speed_mps": 8.,
            "notice_path": "original driver-reference camera and participant positions; observation unresolved",
            "physical_completion_claimed": False, "legal_conclusion": None}


def verify_loaded_site(world_map, plan, driving_lane_type, location_factory):
    site, ego_xy, overtaker_xy, _, _ = load_site(plan["site_source"], plan["site_sha256"])
    if world_map.name != site["map_name"]:
        raise ValueError("Loaded Native map differs from surveyed site")
    result = []
    for label, xy in (("ego", ego_xy), ("overtaker", overtaker_xy)):
        location = location_factory(x=xy[0], y=xy[1], z=0.)
        waypoint = world_map.get_waypoint(location, project_to_road=False, lane_type=driving_lane_type)
        if waypoint is None or waypoint.road_id != site[label + "_road_id"] or waypoint.lane_id != site[label + "_lane_id"]:
            raise ValueError("Loaded Native " + label + " waypoint differs from surveyed site")
        if hypot(waypoint.transform.location.x - xy[0], waypoint.transform.location.y - xy[1]) > .35:
            raise ValueError("Loaded Native " + label + " location differs from surveyed site")
        result.append(waypoint)
    return result


def control(position_xy, forward_xy, velocity_xy, target_xy, target_speed_mps):
    values = (*position_xy, *forward_xy, *velocity_xy, *target_xy, target_speed_mps)
    if not all(isfinite(x) for x in values) or not 0 < target_speed_mps <= 12:
        raise ValueError("Invalid original controller input")
    dx, dy = target_xy[0] - position_xy[0], target_xy[1] - position_xy[1]
    distance = hypot(dx, dy)
    if distance < .3 or hypot(*forward_xy) < .9:
        return {"steer": 0., "throttle": 0., "brake": 1.}
    turn = atan2(forward_xy[0] * dy - forward_xy[1] * dx,
                 forward_xy[0] * dx + forward_xy[1] * dy)
    speed = hypot(*velocity_xy)
    return {"steer": max(-.45, min(.45, .75 * turn)),
            "throttle": max(0., min(.45, .2 * (target_speed_mps - speed))),
            "brake": max(0., min(.45, .2 * (speed - target_speed_mps)))}

"""Retain four original Native cameras and two-vehicle frame observations."""

import json
from pathlib import Path
import subprocess
from threading import Lock


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")


class SourceRecorder:
    def __init__(self, output, camera_sizes, fps=20):
        if fps != 20 or set(camera_sizes) != set(CAMERAS):
            raise ValueError("Four named 20 Hz original cameras required")
        self.output = Path(output)
        self.output.mkdir(parents=True, exist_ok=True)
        self.sizes = camera_sizes
        self.lock = Lock()
        self.encoders = {}
        self.camera_frames = {name: [] for name in CAMERAS}
        self.body = []
        self.closed = False
        try:
            for name in CAMERAS:
                width, height = camera_sizes[name]
                if type(width) is not int or type(height) is not int or min(width, height) < 1:
                    raise ValueError("Invalid original camera dimensions")
                stderr = (self.output / (name + "-encoder.log")).open("wb")
                command = ["ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
                           "-f", "rawvideo", "-pixel_format", "bgra",
                           "-video_size", f"{width}x{height}", "-framerate", "20",
                           "-i", "pipe:0", "-an", "-c:v", "ffv1", "-threads", "1",
                           str(self.output / (name + ".mkv"))]
                try:
                    process = subprocess.Popen(command, stdin=subprocess.PIPE,
                                               stdout=subprocess.DEVNULL, stderr=stderr)
                except BaseException:
                    stderr.close()
                    raise
                self.encoders[name] = process, stderr
        except BaseException:
            self.close()
            raise

    def on_frame(self, name, image):
        with self.lock:
            if self.closed or name not in self.encoders:
                raise ValueError("Original camera recorder closed or unknown")
            width, height = self.sizes[name]
            if (image.width, image.height) != (width, height):
                raise ValueError("Original camera size changed")
            raw = bytes(image.raw_data)
            if len(raw) != width * height * 4:
                raise ValueError("Original camera payload incomplete")
            rows = self.camera_frames[name]
            if rows and image.frame <= rows[-1]["frame"]:
                raise ValueError("Original camera frames out of order")
            process = self.encoders[name][0]
            if process.poll() is not None:
                raise ValueError("Original camera encoder exited early")
            process.stdin.write(raw)
            rows.append({"frame": int(image.frame), "time_s": float(image.timestamp)})

    def record_body(self, row):
        with self.lock:
            if self.closed or not all(key in row for key in
                                      ("frame", "time_s", "road_forward_xy", "ego", "overtaker")):
                raise ValueError("Original overtaking body sample incomplete")
            if self.body and row["frame"] <= self.body[-1]["frame"]:
                raise ValueError("Original body frames out of order")
            if any(len(row[name].get("body_corners_xy_m", [])) != 4 for name in ("ego", "overtaker")):
                raise ValueError("Both original bodies need four footprint corners")
            self.body.append(row)

    def close(self):
        if self.closed:
            return
        self.closed = True
        failures = []
        for name, (process, stderr) in self.encoders.items():
            try:
                if process.stdin and not process.stdin.closed:
                    process.stdin.close()
                if process.wait(timeout=30):
                    failures.append(name)
            finally:
                stderr.close()
        if failures:
            raise ValueError("Original camera encoder failed: " + ", ".join(failures))

    def seal(self):
        self.close()
        frames = [row["frame"] for row in self.body]
        if len(frames) < 3:
            raise ValueError("Original overtaking history incomplete")
        if not (self.output / "overtake_site_original.json").is_file():
            raise ValueError("Verified original Native road site missing")
        for name in CAMERAS:
            rows = self.camera_frames[name]
            video = self.output / (name + ".mkv")
            if not video.is_file() or not video.stat().st_size:
                raise ValueError("Original camera video missing: " + name)
            if [row["frame"] for row in rows] != frames:
                raise ValueError("Original camera/body frame join differs: " + name)
            if any(abs(a["time_s"] - b["time_s"]) > .05 for a, b in zip(rows, self.body)):
                raise ValueError("Original camera/body time join differs: " + name)
        with (self.output / "overtake_bodies_original.jsonl").open("x") as stream:
            for row in self.body:
                stream.write(json.dumps(row, allow_nan=False) + "\n")
        with (self.output / "trace.jsonl").open("x") as stream:
            for row in self.body:
                corners = row["ego"]["body_corners_xy_m"]
                centre = [sum(corner[axis] for corner in corners) / 4 for axis in (0, 1)]
                stream.write(json.dumps({"frame": row["frame"], "time_s": row["time_s"],
                                         "position_m": centre,
                                         "position": {"x": centre[0], "y": centre[1],
                                                      "z": row["ego"]["z_m"]},
                                         "heading_deg": row["ego"]["heading_deg"],
                                         "speed_mps": row["ego"]["speed_mps"]}, allow_nan=False) + "\n")
        with (self.output / "video_frames.jsonl").open("x") as stream:
            for index, row in enumerate(self.body):
                stream.write(json.dumps({"video_frame": index, "carla_frame": row["frame"],
                                         "native_frame": row["frame"], "time_s": row["time_s"]},
                                        allow_nan=False) + "\n")
        for name in CAMERAS:
            with (self.output / (name + "-frames.jsonl")).open("x") as stream:
                for index, row in enumerate(self.camera_frames[name]):
                    stream.write(json.dumps({"video_frame": index, "native_frame": row["frame"],
                                             "time_s": row["time_s"]}, allow_nan=False) + "\n")
        return {"frames": len(frames), "original_cameras": list(CAMERAS),
                "original_body": "overtake_bodies_original.jsonl",
                "original_site": "overtake_site_original.json",
                "frame_map": "video_frames.jsonl"}

"""Source-shaped full-body overtaking geometry and speed history; no legal finding."""
from math import hypot,isfinite


def _number(value):
    return isinstance(value,(int,float)) and not isinstance(value,bool) and isfinite(value)


def _body(record,name):
    body=record.get(name)
    if not isinstance(body,dict) or not body.get('id') or not _number(body.get('speed_mps')) or body['speed_mps']<0:
        raise ValueError('Missing original '+name+' identity or speed')
    corners=body.get('body_corners_xy_m')
    if not isinstance(corners,list) or len(corners)!=4 or any(not isinstance(p,list) or len(p)!=2 or not all(_number(x) for x in p) for p in corners):
        raise ValueError('Missing four original '+name+' body corners')
    if len({tuple(p) for p in corners})!=4:raise ValueError('Duplicate original body corners')
    return body,corners


def measure(frames,ego_id,overtaker_id):
    """Bracket complete passing from original body extents, retaining each 20 Hz sample.

    Each frame supplies original full-body corners and the source-surveyed local
    forward tangent. A positive rear-to-front gap means geometric completion at
    that sample only; the interval between frames remains unresolved.
    """
    if not ego_id or not overtaker_id or ego_id==overtaker_id:
        raise ValueError('Distinct overtaken and overtaking actor IDs required')
    if not isinstance(frames,list) or len(frames)<3:raise ValueError('Need original overtaking history')
    samples=[];previous=None
    for row in frames:
        frame,time=row.get('frame'),row.get('time_s')
        if type(frame) is not int or frame<0 or not _number(time):raise ValueError('Invalid original frame identity')
        if previous is not None and (frame!=previous[0]+1 or abs(time-previous[1]-.05)>1e-6):
            raise ValueError('Original overtaking frames are unordered or not 20 Hz')
        previous=(frame,time)
        direction=row.get('road_forward_xy')
        if not isinstance(direction,list) or len(direction)!=2 or not all(_number(x) for x in direction):raise ValueError('Missing source-surveyed road forward tangent')
        length=hypot(*direction)
        if length<.9 or length>1.1:raise ValueError('Road tangent must be a near-unit original direction')
        forward=[x/length for x in direction];right=[forward[1],-forward[0]]
        ego,ec=_body(row,'ego');overtaker,oc=_body(row,'overtaker')
        if ego['id']!=ego_id or overtaker['id']!=overtaker_id:raise ValueError('Original actor identity changed')
        project=lambda corners,axis:[sum(p[i]*axis[i] for i in (0,1)) for p in corners]
        gap=min(project(oc,forward))-max(project(ec,forward))
        center=lambda corners:[sum(p[i] for p in corners)/4 for i in (0,1)]
        ecen,ocen=center(ec),center(oc)
        lateral=sum((ocen[i]-ecen[i])*right[i] for i in (0,1))
        ego_right=sum(ecen[i]*right[i] for i in (0,1))
        samples.append({'frame':frame,'time_s':time,'rear_to_front_gap_m':gap,
                        'full_body_passed_at_sample':gap>0,'overtaker_lateral_offset_right_m':lateral,
                        'ego_right_projection_m':ego_right,'ego_speed_mps':ego['speed_mps'],
                        'overtaker_speed_mps':overtaker['speed_mps']})
    first=next((i for i,x in enumerate(samples) if x['full_body_passed_at_sample']),None)
    if first==0:raise ValueError('Overtaker already completely ahead in first original frame')
    if first is not None and any(x['full_body_passed_at_sample'] for x in samples[:first]):raise ValueError('Inconsistent pass bracket')
    before=samples[:first] if first is not None else samples
    start=before[0]
    return {'samples':samples,'last_not_complete_frame':before[-1]['frame'],
            'first_complete_frame':samples[first]['frame'] if first is not None else None,
            'completion_interval_s':[before[-1]['time_s'],samples[first]['time_s']] if first is not None else None,
            'max_precompletion_speed_increase_mps':max(x['ego_speed_mps']-start['ego_speed_mps'] for x in before),
            'max_precompletion_step_speed_increase_mps':max((max(0.,b['ego_speed_mps']-a['ego_speed_mps']) for a,b in zip(before,before[1:])),default=0.),
            'completion_interval_speed_change_mps':(samples[first]['ego_speed_mps']-before[-1]['ego_speed_mps']) if first is not None else None,
            'post_completion_overlap_recurrence':any(not x['full_body_passed_at_sample'] for x in samples[first+1:]) if first is not None else None,
            'max_precompletion_right_shift_m':max(x['ego_right_projection_m']-start['ego_right_projection_m'] for x in before),
            'passing_side_at_first_frame':'right' if start['overtaker_lateral_offset_right_m']>0 else 'left' if start['overtaker_lateral_offset_right_m']<0 else 'aligned',
            'observation_or_hearing_confirmed':None,'right_pass_permission_confirmed':None,
            'physical_native_capture_confirmed':False,'legal_conclusion':None}
